e="number" name="input_heads"></label><label data-field="gross_weight_kg"><span>Poids brut (kg) *</span><input required min="0.001" type="number" step="0.001" name="gross_weight_kg"></label><label data-field="tare_weight_kg"><span>Tare / contenant (kg)</span><input min="0" type="number" step="0.001" name="tare_weight_kg" value="0"></label><label data-field="converted_at"><span>Date et heure *</span><input value="<?=e(date('Y-m-d\TH:i'))?>" type="datetime-local" name="converted_at" required></label></div><div class="conversion-weight"><span>Poids net · après validation<strong data-conversion-net aria-live="polite">—</strong></span></div><p class="livestock-guide" data-livestock-context aria-live="polite"></p></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close><i class="bi bi-x-lg" aria-hidden="true"></i><span>Annuler</span></button><button type="submit" class="btn-primary"><i class="bi bi-check2-circle" aria-hidden="true"></i><span>Soumettre pour validation</span></button></footer></form></section><?php endif; ?>